/**
 * Manifest access layer.
 *
 * frontend/public/models/manifest.json is generated by the Z-Anatomy
 * exporter pipeline (scripts/generate_manifest.py) and is the single
 * source of truth for which 3D models exist and where. This module is
 * the ONLY place that knows how to load/parse/validate it — components
 * never fetch or shape-check it themselves.
 *
 * Fetched at runtime (not statically imported) so newly-exported models
 * show up without a frontend rebuild — the whole point of the
 * incremental export pipeline. Cached in module scope after the first
 * successful load; concurrent callers share one in-flight request.
 */

export interface ManifestEntry {
  system: string;
  path: string;
  available: boolean;
}

export type Manifest = Record<string, ManifestEntry>;

export interface ResolvedModel extends ManifestEntry {
  id: string;
}

export class ManifestLoadError extends Error {
  constructor(
    message: string,
    public override readonly cause?: unknown,
  ) {
    super(message);
    this.name = "ManifestLoadError";
  }
}

const MANIFEST_URL = "/models/manifest.json";
const FETCH_TIMEOUT_MS = 8000;

let cachedManifest: Manifest | null = null;
let inFlightRequest: Promise<Manifest> | null = null;

function isManifestEntry(value: unknown): value is ManifestEntry {
  if (typeof value !== "object" || value === null) return false;
  const entry = value as Record<string, unknown>;
  return (
    typeof entry.system === "string" &&
    typeof entry.path === "string" &&
    typeof entry.available === "boolean"
  );
}

function isManifest(value: unknown): value is Manifest {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  return Object.values(value).every(isManifestEntry);
}

/**
 * Loads and validates manifest.json. Throws ManifestLoadError for network
 * failures, timeouts, non-2xx responses, or malformed JSON/shape — callers
 * (via useManifest) decide how to surface that as UI state.
 */
export async function loadManifest(): Promise<Manifest> {
  if (cachedManifest) return cachedManifest;
  if (inFlightRequest) return inFlightRequest;

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);

  inFlightRequest = fetch(MANIFEST_URL, { signal: controller.signal })
    .then(async (response) => {
      if (!response.ok) {
        throw new ManifestLoadError(`manifest.json responded with status ${response.status}`);
      }

      let data: unknown;
      try {
        data = await response.json();
      } catch (parseError) {
        throw new ManifestLoadError("manifest.json is not valid JSON", parseError);
      }

      if (!isManifest(data)) {
        throw new ManifestLoadError("manifest.json has an unexpected shape");
      }

      cachedManifest = data;
      return data;
    })
    .catch((error) => {
      if (error instanceof ManifestLoadError) throw error;
      if (error instanceof DOMException && error.name === "AbortError") {
        throw new ManifestLoadError("Timed out loading manifest.json", error);
      }
      throw new ManifestLoadError("Could not load manifest.json", error);
    })
    .finally(() => {
      clearTimeout(timeout);
      inFlightRequest = null;
    });

  return inFlightRequest;
}

/** Test-only escape hatch — production code never needs to bust the cache. */
export function _resetManifestCacheForTests(): void {
  cachedManifest = null;
  inFlightRequest = null;
}

export function getAllModels(manifest: Manifest): ResolvedModel[] {
  return Object.entries(manifest).map(([id, entry]) => ({ id, ...entry }));
}

export function getModelsBySystem(manifest: Manifest, systemId: string): ResolvedModel[] {
  return getAllModels(manifest).filter((model) => model.system === systemId);
}

export function getModel(manifest: Manifest, id: string): ResolvedModel | undefined {
  const entry = manifest[id];
  return entry ? { id, ...entry } : undefined;
}

export function isModelAvailable(manifest: Manifest, id: string): boolean {
  return manifest[id]?.available === true;
}
